"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["12654"],{50655(e){e.exports=JSON.parse('{"id":"FIN-323","slug":"price-ceiling","term":"Price Ceiling","also_known_as":[],"difficulty":"Intermediate","definition":"A price ceiling is a legal maximum price set by a government that sellers are not allowed to exceed.","explanation":["Governments set price ceilings to make essential goods more affordable, especially during crises or for products seen as necessities, such as rent, basic food, fuel or medicines.","A price ceiling only has an effect if it is set below the equilibrium price. In that case, it lowers the price for buyers, but it also creates a shortage. At the lower price, more people want to buy, while producers are willing to supply less.","For example, if the market price of bread is 3 and the government sets a ceiling of 2, more people want bread at 2, but bakers make less because it is less profitable. The result can be empty shelves, long queues and informal or illegal markets where bread is sold above the legal price.","Price ceilings can also reduce quality, as sellers cut costs, and discourage investment in new supply. Supporters argue they protect people from unaffordable prices, while critics argue that targeted support, such as payments to people on low incomes, can help without creating shortages."],"note":"","total":1725,"prev":{"slug":"pretax-income","term":"Pretax Income"},"next":{"slug":"price-discovery","term":"Price Discovery"}}')}}]);